16	// FakeMsg is a jetstream.Msg for unit-testing a consumer's message disposition
17	// without a live broker. Script the fields the handler reads (SubjectVal,
18	// DataVal, HeadersVal, Meta) and assert the terminal call it made (Acked,
19	// Termed, Naks, NakDelays). Because jetstream.Msg is an interface — unlike the
20	// concrete *nats.Msg whose Ack/Nak/Term hit the wire — the disposition is
21	// directly observable.
22	type FakeMsg struct {
23		SubjectVal string
24		DataVal    []byte
25		HeadersVal nats.Header
26		Meta       *jetstream.MsgMetadata
27		MetaErr    error
28	
29		Acked       bool
30		Termed      bool
31		Naks        int // plain Nak() calls; delayed naks land in NakDelays
32		NakDelays   []time.Duration
33		InProgressN int
34	}
35	
36	func (m *FakeMsg) Subject() string      { return m.SubjectVal }
37	func (m *FakeMsg) Data() []byte         { return m.DataVal }
38	func (m *FakeMsg) Headers() nats.Header { return m.HeadersVal }
39	func (m *FakeMsg) Reply() string        { return "" }
40	
41	// Metadata returns the scripted metadata, the scripted error, or — when neither
42	// is set — a non-JetStream error, matching how *nats.Msg.Metadata behaves for a
43	// message that carries none. Consumers guard this with `if err == nil`.
44	func (m *FakeMsg) Metadata() (*jetstream.MsgMetadata, error) {
45		if m.MetaErr != nil {
46			return nil, m.MetaErr
47		}
48		if m.Meta != nil {
49			return m.Meta, nil
50		}
51		return nil, errors.New("fakemsg: no metadata set")
52	}
53	
54	func (m *FakeMsg) Ack() error                      { m.Acked = true; return nil }
55	func (m *FakeMsg) DoubleAck(context.Context) error { m.Acked = true; return nil }
56	func (m *FakeMsg) Nak() error                      { m.Naks++; return nil }
57	func (m *FakeMsg) NakWithDelay(d time.Duration) error {
58		m.NakDelays = append(m.NakDelays, d)
59		return nil
60	}
61	func (m *FakeMsg) InProgress() error           { m.InProgressN++; return nil }
62	func (m *FakeMsg) Term() error                 { m.Termed = true; return nil }
63	func (m *FakeMsg) TermWithReason(string) error { m.Termed = true; return nil }
64	
65	var _ jetstream.Msg = (*FakeMsg)(nil)
