90	// outruns AckWait/3 gets InProgress heartbeats, and the heartbeat goroutine has
91	// stopped by the time Process returns (no further ticks accrue).
92	func TestProcessKeepInProgress(t *testing.T) {
93		cfg := testCfg
94		cfg.KeepInProgress = true
95		cfg.AckWait = 30 * time.Millisecond // ticks at 10ms
96	
97		msg := &natsmsgtest.FakeMsg{DataVal: []byte("payload")}
98		decode := func(b []byte) (string, error) { return string(b), nil }
99		handle := func(context.Context, trace.Span, jetstream.Msg, string) {
100			time.Sleep(35 * time.Millisecond) // spans at least three ticks
101		}
102		Process(context.Background(), msg, cfg, decode, handle, nil)
103	
