		FilterSubject:     "events.repo",
		Name:              "testconsumer",
		SpanName:          "test.consume",
		InactiveThreshold: 72 * time.Hour,
		MaxAckPending:     42,
	}, func(jetstream.Msg) {})
	if err != nil {
