package natsmsg

import (
	"context"
	"fmt"
	"time"

	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/trace"
)

// DefaultPublishTimeout bounds the wait for the broker's publish
// acknowledgment when Publisher.Timeout is zero. The bound matters because
// Entire connections reconnect forever and nats.go buffers publishes while
// disconnected: without it, a publisher holding an HTTP request or a message
// disposition would wait indefinitely behind an unreachable broker instead
// of failing over to its retry path (the caller's outbox, nak, or 5xx).
const DefaultPublishTimeout = 5 * time.Second

// StartProducerSpan opens a producer span named name on tr, pre-tagged with
// the standard messaging attributes (system=nats, destination=subject) — the
// publish-side counterpart of [StartConsumerSpan]. Extra attrs are appended.
// The caller owns the span and must End it, and should Inject the returned
// ctx into the outgoing message so the consumer can re-parent.
func StartProducerSpan(ctx context.Context, tr trace.Tracer, subject, name string, attrs ...attribute.KeyValue) (context.Context, trace.Span) {
	base := append([]attribute.KeyValue{
		attribute.String("messaging.system", "nats"),
		attribute.String("messaging.destination.name", subject),
	}, attrs...)
	return tr.Start(ctx, name, trace.WithSpanKind(trace.SpanKindProducer), trace.WithAttributes(base...)) //nolint:spancheck // the caller owns the span and Ends it
}

// Publisher is the JetStream publish core shared by Entire's producers: a
// producer span, W3C trace-context injection, Nats-Msg-Id dedup, and a
// bounded wait for the broker's ack. Every service had grown its own copy of
// exactly this prologue around PublishMsg; Publisher owns the prologue and
// nothing else — subject construction, payload encoding, and the response to
// a failed publish (outbox retry, nak, HTTP 5xx) stay with the caller.
type Publisher struct {
	// JS is the JetStream context to publish through.
	JS jetstream.JetStream
	// Tracer opens the producer span; nil uses the global OTel tracer
	// provider.
	Tracer trace.Tracer
	// Timeout bounds the wait for the broker's PubAck; 0 uses
	// DefaultPublishTimeout. It derives from the caller's ctx, so an
	// already-cancelled ctx still fails fast.
	Timeout time.Duration
}

// Publish sends msg and waits — bounded by Timeout — for the broker's ack,
// wrapped in a producer span named "publish <subject>". A non-empty msgID is
// set as the Nats-Msg-Id header, the broker-side dedup key within the
// stream's duplicate window; empty leaves any Nats-Msg-Id already on msg
// untouched. Trace context from ctx is injected into msg's headers (msg is
// mutated) so the consumer span re-parents across the hop.
//
// The returned PubAck reports where the message landed and whether the
// broker deduplicated it (PubAck.Duplicate) — a duplicate is a normal
// outcome for an at-least-once producer retrying, not an error. The
// stream, sequence, and duplicate outcome are also recorded on the span.
func (p Publisher) Publish(ctx context.Context, msg *nats.Msg, msgID string) (*jetstream.PubAck, error) {
	tr := p.Tracer
	if tr == nil {
		tr = otel.Tracer("github.com/entireio/go-nuts/natsmsg")
	}
	ctx, span := StartProducerSpan(ctx, tr, msg.Subject, "publish "+msg.Subject)
	defer span.End()

	if msgID != "" {
		if msg.Header == nil {
			msg.Header = nats.Header{}
		}
		msg.Header.Set(nats.MsgIdHdr, msgID)
		span.SetAttributes(attribute.String("messaging.message.id", msgID))
	}
	Inject(ctx, msg)

	timeout := p.Timeout
	if timeout == 0 {
		timeout = DefaultPublishTimeout
	}
	pubCtx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()

	ack, err := p.JS.PublishMsg(pubCtx, msg)
	if err != nil {
		span.RecordError(err)
		span.SetStatus(codes.Error, "publish")
		return nil, fmt.Errorf("natsmsg: publish %s: %w", msg.Subject, err)
	}
	span.SetAttributes(
		attribute.String("messaging.nats.stream", ack.Stream),
		attribute.Int64("messaging.nats.sequence", ClampToInt64(ack.Sequence)),
		attribute.Bool("messaging.nats.duplicate", ack.Duplicate),
	)
	return ack, nil
}

package natsmsg

import (
	"context"
	"testing"
	"time"

	natsserver "github.com/nats-io/nats-server/v2/server"
	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"
)

// runJetStreamEnv boots an embedded JetStream server with a stream bound to
// pub.> and returns a JetStream context for it.
func runJetStreamEnv(t *testing.T) jetstream.JetStream {
	t.Helper()
	s, err := natsserver.NewServer(&natsserver.Options{
		Host:      "127.0.0.1",
		Port:      -1, // pick a free port
		NoLog:     true,
		NoSigs:    true,
		JetStream: true,
		StoreDir:  t.TempDir(),
	})
	if err != nil {
		t.Fatalf("new embedded nats server: %v", err)
	}
	go s.Start()
	if !s.ReadyForConnections(10 * time.Second) {
		t.Fatal("embedded nats server not ready in time")
	}
	t.Cleanup(s.Shutdown)

	nc, err := nats.Connect(s.ClientURL())
	if err != nil {
		t.Fatalf("connect: %v", err)
	}
	t.Cleanup(nc.Close)
	js, err := jetstream.New(nc)
	if err != nil {
		t.Fatalf("jetstream.New: %v", err)
	}
	if _, err := js.CreateStream(context.Background(), jetstream.StreamConfig{
		Name:       "pub_v1",
		Subjects:   []string{"pub.>"},
		Duplicates: time.Minute,
	}); err != nil {
		t.Fatalf("create stream: %v", err)
	}
	return js
}

// TestPublisherStampsHeadersAndAcks drives the whole publish prologue: the
// stored message must carry the Nats-Msg-Id dedup key and the producer's
// injected trace context, and the ack must report the landing stream.
func TestPublisherStampsHeadersAndAcks(t *testing.T) {
	js := runJetStreamEnv(t)
	ctx, _, _ := remoteSpanCtxT(t)

	p := Publisher{JS: js}
	ack, err := p.Publish(ctx, &nats.Msg{Subject: "pub.repo", Data: []byte("payload")}, "msg-1")
	if err != nil {
		t.Fatalf("publish: %v", err)
	}
	if ack.Stream != "pub_v1" {
		t.Errorf("ack stream = %q, want pub_v1", ack.Stream)
	}
	if ack.Duplicate {
		t.Error("first publish reported as duplicate")
	}

	stream, err := js.Stream(context.Background(), "pub_v1")
	if err != nil {
		t.Fatalf("bind stream: %v", err)
	}
	stored, err := stream.GetMsg(context.Background(), ack.Sequence)
	if err != nil {
		t.Fatalf("get stored msg: %v", err)
	}
	if got := stored.Header.Get(nats.MsgIdHdr); got != "msg-1" {
		t.Errorf("stored Nats-Msg-Id = %q, want msg-1", got)
	}
	if got := stored.Header.Get("traceparent"); got == "" {
		t.Error("stored message has no traceparent header; trace context was not injected")
	}
}

// TestPublisherDedupesByMsgID: a second publish with the same msg-id inside
// the duplicate window must be suppressed broker-side and reported as such —
// the normal outcome for an at-least-once producer retrying, not an error.
func TestPublisherDedupesByMsgID(t *testing.T) {
	js := runJetStreamEnv(t)
	p := Publisher{JS: js}

	first, err := p.Publish(context.Background(), &nats.Msg{Subject: "pub.repo", Data: []byte("x")}, "dup-1")
	if err != nil {
		t.Fatalf("first publish: %v", err)
	}
	second, err := p.Publish(context.Background(), &nats.Msg{Subject: "pub.repo", Data: []byte("x")}, "dup-1")
	if err != nil {
		t.Fatalf("second publish: %v", err)
	}
	if !second.Duplicate {
		t.Error("second publish with the same msg-id not reported as duplicate")
	}
	if second.Sequence != first.Sequence {
		t.Errorf("duplicate ack sequence = %d, want the original %d", second.Sequence, first.Sequence)
	}
}

// TestPublisherEmptyMsgIDLeavesHeader: an empty msgID must not clobber a
// Nats-Msg-Id the caller already set on the message.
func TestPublisherEmptyMsgIDLeavesHeader(t *testing.T) {
	js := runJetStreamEnv(t)
	p := Publisher{JS: js}

	msg := &nats.Msg{Subject: "pub.repo", Data: []byte("x"), Header: nats.Header{}}
	msg.Header.Set(nats.MsgIdHdr, "preset-1")
	ack, err := p.Publish(context.Background(), msg, "")
	if err != nil {
		t.Fatalf("publish: %v", err)
	}
	stream, err := js.Stream(context.Background(), "pub_v1")
	if err != nil {
		t.Fatalf("bind stream: %v", err)
	}
	stored, err := stream.GetMsg(context.Background(), ack.Sequence)
	if err != nil {
		t.Fatalf("get stored msg: %v", err)
	}
	if got := stored.Header.Get(nats.MsgIdHdr); got != "preset-1" {
		t.Errorf("stored Nats-Msg-Id = %q, want the caller's preset-1", got)
	}
}

// TestPublisherErrorsOnUnboundSubject: a subject no stream listens on must
// surface as an error (the broker sends no ack), not hang past the bound.
func TestPublisherErrorsOnUnboundSubject(t *testing.T) {
	js := runJetStreamEnv(t)
	p := Publisher{JS: js, Timeout: 500 * time.Millisecond}

	start := time.Now()
	if _, err := p.Publish(context.Background(), &nats.Msg{Subject: "unbound.subject", Data: []byte("x")}, "m"); err == nil {
		t.Fatal("publish to an unbound subject succeeded, want error")
	}
	if elapsed := time.Since(start); elapsed > 5*time.Second {
		t.Errorf("publish error took %v, want it bounded well under the default", elapsed)
	}
}

// remoteSpanCtxT adapts the tracecontext_test helper for use here (same
// package, shared TestMain propagator setup).
func remoteSpanCtxT(t *testing.T) (context.Context, string, string) {
	t.Helper()
	ctx, tid, sid := remoteSpanCtx(t)
	return ctx, tid.String(), sid.String()
}

